import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', description: '', telephone: '',
    tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [availableMatieres, setAvailableMatieres] = useState([]);
  const [saved, setSaved] = useState(false);

  // Modales
  const [showUpload, setShowUpload] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
        const res = await api.get(route);
        setForm(res.data);

        // Charger les matières créées par l'ADMIN
        const resMat = await api.get('/api/admin/referentiel/matieres');
        setAvailableMatieres(resMat.data);
      } catch (e) { console.error("Erreur chargement"); }
    };
    fetchData();
  }, [user]);

  // --- 1. GESTION PHOTO DE PROFIL ---
  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setForm({ ...form, photo_url: res.data.url });
      alert("Photo mise à jour !");
    } catch (e) { alert("Erreur upload photo"); }
  };

  // --- 2. GESTION DES TARIFS ---
  const handleToggleMatiere = (matiere_id) => {
    let updated = [...(form.tarifs_matieres || [])];
    const index = updated.findIndex(t => t.matiere_id === matiere_id);
    if (index > -1) {
      updated = updated.filter(t => t.matiere_id !== matiere_id);
    } else {
      updated.push({ matiere_id, tarif: 20 }); // Prix par défaut
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handleTarifChange = (matiere_id, val) => {
    const updated = form.tarifs_matieres.map(t => 
      t.matiere_id === matiere_id ? { ...t, tarif: parseFloat(val) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  // --- 3. ENREGISTREMENT GLOBAL ---
  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      // On envoie les données modifiables au backend
      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        bio: form.bio,
        telephone: form.telephone,
        matieres_avec_tarifs: form.tarifs_matieres 
      };
      await api.put(route, payload);
      setSaved(true); setTimeout(() => setSaved(false), 2000);
    } catch (e) { alert('Erreur sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  return (
    <div style={{ padding: 32, maxWidth: 1100, margin: '0 auto' }}>

      {/* HEADER AVEC PHOTO (Image 1 améliorée) */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 30, background: 'var(--card)', padding: 24, borderRadius: 20, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 100, height: 100, borderRadius: '50%', overflow: 'hidden', background: 'var(--surface2)', border: '3px solid var(--accent)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://via.placeholder.com/100'} alt="Profil" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          <label style={{ position: 'absolute', bottom: 0, right: 0, background: 'var(--accent)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
            📷 <input type="file" hidden onChange={handlePhotoUpload} />
          </label>
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)' }}>{form.email} • <span style={{ color: form.statut_validation === 'validé' ? 'var(--accent3)' : 'var(--accent2)' }}>{form.statut_validation}</span></p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 30 }}>

        {/* IDENTITÉ MODIFIABLE */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
          <div style={{ fontWeight: 600, marginBottom: 20 }}>👤 Informations personnelles</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
             <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                <div><label>Prénom</label><input style={inp} value={form.user_prenom || ''} onChange={e => setForm({...form, user_prenom: e.target.value})} /></div>
                <div><label>Nom</label><input style={inp} value={form.user_nom || ''} onChange={e => setForm({...form, user_nom: e.target.value})} /></div>
             </div>
             <div><label>Ville</label><input style={inp} value={form.ville || ''} onChange={e => setForm({...form, ville: e.target.value})} /></div>
             <div><label>Téléphone</label><input style={inp} value={form.telephone || ''} onChange={e => setForm({...form, telephone: e.target.value})} /></div>
             <button onClick={handleSave} style={{ background: 'var(--accent)', color: '#fff', border: 'none', padding: 12, borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}>
               {saved ? '✅ Modifié avec succès' : 'Enregistrer le profil'}
             </button>
          </div>
        </div>

        {/* MATIÈRES DE L'ADMIN (Image 3 & 4) */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24 }}>
          <div style={{ fontWeight: 600, marginBottom: 16 }}>📚 Matières & Tarifs</div>
          <div style={{ maxHeight: 400, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 8 }}>
            {availableMatieres.map(m => {
              const active = form.tarifs_matieres?.find(t => t.matiere_id === m.id);
              return (
                <div key={m.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: 12, background: active ? 'rgba(108,99,255,0.1)' : 'var(--surface2)', borderRadius: 10, border: active ? '1px solid var(--accent)' : '1px solid transparent' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <input type="checkbox" checked={!!active} onChange={() => handleToggleMatiere(m.id)} />
                    <span>{m.nom}</span>
                  </div>
                  {active && (
                    <input type="number" value={active.tarif} onChange={e => handleTarifChange(m.id, e.target.value)} style={{ ...inp, width: 70 }} />
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
